        };
        catalog.state.recent_headers = vec![invalid.clone()];
        assert!(catalog.encode().is_err());
        invalid.base_fee_per_gas = Some(1);
        invalid.extra_data = vec![0; 33].into();
        catalog.state.recent_headers = vec![invalid];
